@once
<style>.execution-inputs .formgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:14px;margin:12px 0}.execution-inputs label{display:block;font-size:13px}.execution-inputs input:not([type=checkbox]),.execution-inputs select,.execution-inputs textarea{width:100%;margin:6px 0 10px;border:1px solid #ffffff30;border-radius:10px;background:#101e2c;color:#e8f0f7;padding:10px}.execution-inputs textarea{min-height:78px}.execution-inputs input[type=checkbox]{margin-right:6px}.execution-inputs h4{font-weight:650;margin-top:18px}.execution-inputs .rowedit{border:1px solid #ffffff25;padding:14px;border-radius:12px;margin:12px 0}.execution-inputs .muted{font-size:12px;color:#adc2d0}.execution-inputs button{border:1px solid #ffffff30;border-radius:10px;padding:9px 14px;margin:8px 0}.execution-inputs .check{padding:12px 0;border-bottom:1px solid #ffffff20}</style>
@endonce
